package org.cloudburstmc.protocol.bedrock.codec.v924.serializer;
import io.netty.buffer.ByteBuf; import lombok.AccessLevel; import lombok.RequiredArgsConstructor; import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper; import org.cloudburstmc.protocol.bedrock.codec.BedrockPacketSerializer; import org.cloudburstmc.protocol.bedrock.packet.ClientboundTextureShiftPacket; import org.cloudburstmc.protocol.common.util.VarInts; import java.util.*;
@RequiredArgsConstructor(access=AccessLevel.PROTECTED) public class ClientboundTextureShiftSerializer_v924 implements BedrockPacketSerializer<ClientboundTextureShiftPacket>{public static final ClientboundTextureShiftSerializer_v924 INSTANCE=new ClientboundTextureShiftSerializer_v924();public void serialize(ByteBuf b,BedrockCodecHelper h,ClientboundTextureShiftPacket p){b.writeByte(p.getAction().ordinal());h.writeString(b,p.getCollectionName());h.writeString(b,p.getFromStep());h.writeString(b,p.getToStep());h.writeArray(b,p.getAllSteps(),h::writeString);VarInts.writeUnsignedLong(b,p.getCurrentLengthTicks());VarInts.writeUnsignedLong(b,p.getTotalLengthTicks());b.writeBoolean(p.isEnabled());}public void deserialize(ByteBuf b,BedrockCodecHelper h,ClientboundTextureShiftPacket p){p.setAction(ClientboundTextureShiftPacket.Action.values()[b.readUnsignedByte()]);p.setCollectionName(h.readString(b));p.setFromStep(h.readString(b));p.setToStep(h.readString(b));List<String>s=new ArrayList<>();h.readArray(b,s,h::readString);p.setAllSteps(s);p.setCurrentLengthTicks(VarInts.readUnsignedLong(b));p.setTotalLengthTicks(VarInts.readUnsignedLong(b));p.setEnabled(b.readBoolean());}}
